function initTodayEditor(){options("todayEditType",C.types.map(k=>[k,C.labels[k]]));options("todayEditGame",["crate","robot","sniper","atbats","disc"].map(k=>[k,C.games[k]]));options("todayEditGoal",[["auto","Individual needs"],["command","Command"],["precision","Precision"],["sequence","Sequencing"],["engagement","Engagement"]]);$("todayEditType").onchange=$("todayEditGame").onchange=editorControls;$("todayEditCancel").onclick=()=>$("todayEditor").close();$("todayEditSave").onclick=()=>{const error=t=>$("todayEditError").textContent=t;if(!todayEditing||C.day()!==today){error("Date changed. Reload Coach Center.");return;}const r=S.read(),W=WorkloadIntelligence,T=TrainingCalendar;if(!r.ok){error("Storage unavailable.");return;}const c=C.clean(r.roster.coach,r.roster.players);c.workload=W.clean(c.workload);const req={...todayEditing,type:$("todayEditType").value,game:$("todayEditGame").value,cap:$("todayEditCap").value===""?null:Number($("todayEditCap").value),pitches:[...$("todayEditPitches").querySelectorAll("input:checked")].map(b=>b.value),goal:$("todayEditGoal").value,note:$("todayEditNote").value};const snapshot=CoachOverview.snapshot(C,W,r.roster,c,req.player,today);if(JSON.stringify(snapshot)!==JSON.stringify(req.snapshot)||T.review(C,W,r.roster,c,req.player,today,today).key!==req.reviewKey){error("New records arrived. Cancel and reopen to review.");return;}const result=T.edit(C,W,r.roster,c,req,today);if(!result.ok){error(result.error);return;}if(req.id)c.plans=c.plans.map(p=>p.id===req.id?result.plan:p);else c.plans.push(result.plan);if($("todayEditReviewed").checked){const flags=W.checkin(c,req.player,today);if(req.type==="training"&&flags&&(flags.pain||flags.limited||flags.concern)){error("Athlete reported a concern. Choose rest/recovery or save without confirming.");return;}if(req.type==="training"&&!T.acknowledge(C,W,r.roster,c,req.player,today,today)){error("Cannot confirm this assignment.");return;}c.workload.seen[req.player]=snapshot;}if(!S.write({...r.roster,coach:c})){error("Save failed.");return;}$("todayEditor").close();refreshToday();notice($("todayEditReviewed").checked&&req.type==="training"?"Today’s training plan confirmed. Other days unchanged.":"Today’s plan saved. Other days unchanged.");};}

